/// The unchanged ledger has no table column. Positive result versions denote
/// objects; zero denotes an unversioned append result, whose id identifies its
/// log/xref kind. Negative versions denote candidate-state results (the negated
/// candidate version). Keys remain global per Device, never scoped to this enum.
#[derive(Clone, Copy)]
pub(crate) enum MutationTarget {
    Object,
    Log,
    ExternalReference,
    Candidate,
}

impl MutationTarget {
    fn table(self) -> &'static str {
        match self {
            Self::Object => "objects",
            Self::Log => "logs",
            Self::ExternalReference => "external_references",
            Self::Candidate => "advisory_candidates",
        }
    }

    fn accepts(self, recorded: &RecordedMutation) -> bool {
        match self {
            Self::Object => recorded.result_version > 0,
            Self::Candidate => {
                recorded.result_version < 0
                    && ubu_core::AdvisoryCandidateId::parse(&recorded.result_object_id).is_ok()
            }
            Self::Log | Self::ExternalReference => {
                let expected = match self {
                    Self::Log => ObjectType::LogEntry,
                    _ => ObjectType::ExternalReference,
                };
                recorded.result_version == 0
                    && UbuId::parse(&recorded.result_object_id)
                        .and_then(|id| id.require_object_type(expected))
                        .is_ok()
            }
        }
    }
}

pub(crate) struct PreparedMutation {
    pub(crate) canonical_payload: String,
    pub(crate) replay: Option<RecordedMutation>,
}

/// Validate and check the shared device-scoped ledger before any preconditions.
/// Payload equality is unchanged for admit_object and applies to record.payload
/// for append-only writers. A same-payload key cannot switch result tables.
pub(crate) async fn prepare_mutation(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    payload: &Value,
    target: MutationTarget,
) -> Result<PreparedMutation> {
    envelope.validate()?;
    let key = envelope.mutation_key();
    let canonical_payload = String::from_utf8(canonical_payload_bytes(payload))
        .expect("canonical JSON bytes are UTF-8");
    let replay = lookup_mutation(&mut *connection, &key).await?;
    if let Some(recorded) = &replay {
        if recorded.canonical_payload != canonical_payload {
            return Err(ubu_core::UbuError::IdempotencyKeyConflict {
                origin_device_id: key.origin_device_id.as_str().to_owned(),

            Self::Log(_) => None,
        }
    }
    pub fn as_log(&self) -> Option<&LogRecord> {
        match self {
            Self::Log(record) => Some(record),
            Self::Object(_) => None,
        }
    }
}

/// Atomically admit ordered canonical writes. Later preconditions observe
/// earlier writes. Replay retains the ordinary writers' current-state semantics.
/// Only this outer writer owns commit or rollback; no transaction escapes it.
pub async fn admit_batch(pool: &SqlitePool, writes: Vec<BatchWrite>) -> Result<Vec<BatchResult>> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let mut seen = std::collections::HashSet::new();
        let mut results = Vec::with_capacity(writes.len());
        for write in writes {
            let envelope = match &write {
                BatchWrite::Object { envelope, .. } | BatchWrite::Log { envelope, .. } => envelope,
            };
            // prepare_mutation intentionally permits same-payload replay. Within
            // one request, even identical repeated keys are a caller error.
            if !seen.insert(envelope.mutation_key()) {
                return Err(ubu_core::UbuError::IdempotencyKeyConflict {
                    origin_device_id: envelope.origin_device_id.as_str().to_owned(),
                    idempotency_key: envelope.idempotency_key.as_str().to_owned(),
                }
                .into());
            }
            results.push(match write {
                BatchWrite::Object { envelope, record } => {
                    let prepared = prepare_mutation(
                        &mut transaction,
                        &envelope,
                        &record.payload,
                        MutationTarget::Object,
                    )
                    .await?;
                    BatchResult::Object(
                        admit_prepared_object(&mut transaction, &envelope, record, prepared)
                            .await?,
                    )
                }
                BatchWrite::Log { envelope, record } => {
                    let prepared = prepare_mutation(
                        &mut transaction,
                        &envelope,
                        &record.payload,
                        MutationTarget::Log,
                    )
                    .await?;
                    BatchResult::Log(
                        append_prepared_log(&mut transaction, &envelope, record, prepared).await?,
                    )
                }
            });
        }
        Ok(results)
    }
    .await;
    finish_mutation(transaction, result).await
}

